    id: opts.id ?? 'p1', name: 'Tester', typeId: 'minecraft:player', dimension: dim,
    location: opts.location ?? { x: 0.5, y: 0, z: 0.5 }, rotation: opts.rotation ?? { x: 0, y: 0 },
    selectedSlotIndex: 0, isSneaking: false, msgs, inv,
    sendMessage(m) { msgs.push(typeof m === 'string' ? m : JSON.stringify(m)); },
